import asyncio
import os
import queue
import threading
from typing import Generator, Optional

import speech_recognition as sr
from azure.cognitiveservices.speech import ResultReason, SpeechConfig, SpeechRecognizer, AudioConfig, PropertyId
import azure.cognitiveservices.speech as speechsdk


class MicrophoneAudioStream:
    def __init__(self, sample_rate: int = 16000, chunk_size: int = 1024):
        self.sample_rate = sample_rate
        self.chunk_size = chunk_size
        self._q: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._recognizer = sr.Recognizer()
        self._mic = sr.Microphone(sample_rate=sample_rate, chunk_size=chunk_size)
        self._stop_event = threading.Event()
        self._listener: Optional[threading.Thread] = None

    def start(self):
        def _callback(recognizer, audio: sr.AudioData):
            if self._stop_event.is_set():
                return
            try:
                self._q.put(audio.get_raw_data(convert_rate=self.sample_rate, convert_width=2))
            except Exception:
                pass

        with self._mic as source:
            self._recognizer.adjust_for_ambient_noise(source, duration=0.5)

        self._stop_event.clear()
        self._listener = self._recognizer.listen_in_background(self._mic, _callback)
        return self

    def stop(self):
        self._stop_event.set()
        if self._listener is not None:
            self._listener(wait_for_stop=False)
            self._listener = None
        self._q.put(None)

    def read(self) -> Optional[bytes]:
        return self._q.get()


class AzureStreamingSTT:
    def __init__(self, language: str = "en-US", sample_rate: int = 16000):
        key = os.environ.get("AZURE_SPEECH_KEY")
        region = os.environ.get("AZURE_SPEECH_REGION")
        if not key or not region:
            raise RuntimeError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self.sample_rate = sample_rate
        self.speech_config = SpeechConfig(subscription=key, region=region)
        self.speech_config.speech_recognition_language = language
        self.speech_config.set_property(PropertyId.SpeechServiceConnection_InitialSilenceTimeoutMs, "5000")
        self.speech_config.set_property(PropertyId.SpeechServiceConnection_EndSilenceTimeoutMs, "1000")

    def stream_mic_transcripts(self) -> Generator[str, None, None]:
        mic_stream = MicrophoneAudioStream(sample_rate=self.sample_rate).start()
        push_stream = speechsdk.audio.PushAudioInputStream(
            stream_format=speechsdk.audio.AudioStreamFormat(
                samples_per_second=self.sample_rate,
                bits_per_sample=16,
                channels=1,
            )
        )
        audio_config = AudioConfig(stream=push_stream)
        recognizer = SpeechRecognizer(speech_config=self.speech_config, audio_config=audio_config)

        interim_q: "queue.Queue[str]" = queue.Queue()
        stop_flag = threading.Event()

        def _recognized(evt):
            if evt.result.reason == ResultReason.RecognizedSpeech and evt.result.text:
                interim_q.put(evt.result.text)

        def _recognizing(evt):
            if evt.result.text:
                interim_q.put(evt.result.text)

        def _canceled(evt):
            stop_flag.set()

        def _session_stopped(evt):
            stop_flag.set()

        recognizer.recognizing.connect(_recognizing)
        recognizer.recognized.connect(_recognized)
        recognizer.canceled.connect(_canceled)
        recognizer.session_stopped.connect(_session_stopped)

        recognizer.start_continuous_recognition_async().get()

        def _feed_audio():
            try:
                while not stop_flag.is_set():
                    chunk = mic_stream.read()
                    if chunk is None:
                        break
                    push_stream.write(chunk)
            finally:
                try:
                    push_stream.close()
                except Exception:
                    pass

        feeder = threading.Thread(target=_feed_audio, daemon=True)
        feeder.start()

        try:
            while not stop_flag.is_set() or not interim_q.empty():
                try:
                    yield interim_q.get(timeout=0.1)
                except queue.Empty:
                    continue
        finally:
            stop_flag.set()
            mic_stream.stop()
            try:
                recognizer.stop_continuous_recognition_async().get()
            except Exception:
                pass


def stream_mic_transcripts(language: str = "en-US") -> Generator[str, None, None]:
    return AzureStreamingSTT(language=language).stream_mic_transcripts()
